-- 04_comentarios_y_comparativa.sql: Comentarios y degustación comparativa (requiere 01 y 02)

CREATE TABLE "comentarios" (
  "comentario_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "ensayo_id" BIGINT NOT NULL,
  "etapa_id" INTEGER NOT NULL,
  "fecha" TIMESTAMP DEFAULT (CURRENT_TIMESTAMP),
  "texto" TEXT NOT NULL,
  PRIMARY KEY ("comentario_id")
);

CREATE TABLE "degustacion_comparativa" (
  "comparacion_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "campana" TEXT NOT NULL,
  "sitio_id" TEXT NOT NULL,
  "mas_atractiva_vista_variedad_id" TEXT,
  "menos_atractiva_vista_variedad_id" TEXT,
  "mejor_aroma_variedad_id" TEXT,
  "peor_aroma_variedad_id" TEXT,
  "mejor_sabor_variedad_id" TEXT,
  "peor_sabor_variedad_id" TEXT,
  "mejor_equilibrio_variedad_id" TEXT,
  "peor_equilibrio_variedad_id" TEXT,
  "mejor_textura_variedad_id" TEXT,
  "peor_textura_variedad_id" TEXT,
  "volveria_elegir_variedad_id" TEXT,
  "no_volveria_elegir_variedad_id" TEXT,
  "por_que_favorito" TEXT,
  "motivo_no_comparo" TEXT,
  PRIMARY KEY ("comparacion_id")
);

CREATE INDEX "idx_comentarios_ensayo" ON "comentarios" ("ensayo_id");

CREATE UNIQUE INDEX "uq_degustacion_comp_sesion" ON "degustacion_comparativa" ("campana", "sitio_id");

ALTER TABLE "comentarios" ADD FOREIGN KEY ("ensayo_id") REFERENCES "ensayos" ("ensayo_id") ON DELETE CASCADE ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "comentarios" ADD FOREIGN KEY ("etapa_id") REFERENCES "etapas" ("etapa_id") ON DELETE RESTRICT ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

